//! Project issues, view-owned revision clouds and title-block revision tables.
use serde::{Deserialize,Serialize};
use crate::{Document,Element,Id,Point};
use crate::curve::Curve;

#[derive(Debug,Clone,Copy,Default,PartialEq,Eq,Serialize,Deserialize)]
#[serde(rename_all="snake_case")]
pub enum NumberingScope{#[default] Project,Sheet}
#[derive(Debug,Clone,Copy,Default,PartialEq,Eq,Serialize,Deserialize)]
#[serde(rename_all="snake_case")]
pub enum NumberingKind{#[default] Numeric,Alphanumeric,None}
#[derive(Debug,Clone,PartialEq,Serialize,Deserialize)]
#[serde(default)]
pub struct RevisionSequence{pub id:String,pub name:String,pub kind:NumberingKind,pub start:u32,pub digits:usize,pub prefix:String,pub suffix:String,pub values:Vec<String>}
impl Default for RevisionSequence{fn default()->Self{Self{id:"numeric".into(),name:"Numeric".into(),kind:NumberingKind::Numeric,start:1,digits:1,prefix:String::new(),suffix:String::new(),values:vec![]}}}
#[derive(Debug,Clone,PartialEq,Serialize,Deserialize)]
#[serde(default)]
pub struct RevisionSettings{pub numbering:NumberingScope,pub arc_length_mm:f64,pub sequences:Vec<RevisionSequence>}
impl Default for RevisionSettings{fn default()->Self{let numeric=RevisionSequence::default();let letters=RevisionSequence{id:"letters".into(),name:"Alphanumeric".into(),kind:NumberingKind::Alphanumeric,values:(b'A'..=b'Z').map(|c|(c as char).to_string()).collect(),..RevisionSequence::default()};Self{numbering:NumberingScope::Project,arc_length_mm:6.0,sequences:vec![numeric,letters,RevisionSequence{id:"none".into(),name:"None".into(),kind:NumberingKind::None,..RevisionSequence::default()}]}}}

#[derive(Debug,Clone,Copy,Default,PartialEq,Eq,Serialize,Deserialize)]
#[serde(rename_all="snake_case")]
pub enum RevisionVisibility{#[default] CloudsAndTags,TagsOnly,None}
#[derive(Debug,Clone,PartialEq,Serialize,Deserialize)]
pub struct Revision{pub order:u32,pub sequence:String,#[serde(default)]pub date:String,#[serde(default)]pub description:String,#[serde(default)]pub issued_to:String,#[serde(default)]pub issued_by:String,#[serde(default)]pub issued:bool,#[serde(default)]pub visibility:RevisionVisibility}
#[derive(Debug,Clone,PartialEq,Serialize,Deserialize)]
pub struct RevisionCloud{pub view:Id,pub revision:Id,pub curves:Vec<Curve>,#[serde(default)]pub inverted:bool,#[serde(default)]pub pinned:bool,#[serde(default)]pub comments:String,#[serde(default)]pub mark:String}
#[derive(Debug,Clone,PartialEq,Serialize,Deserialize)]
pub struct RevisionTag{pub view:Id,pub cloud:Id,pub at:Point,#[serde(default)]pub family:Option<Id>,#[serde(default)]pub leader:bool,#[serde(default)]pub pinned:bool}
#[derive(Debug,Clone,PartialEq,Serialize,Deserialize)]
#[serde(default)]
pub struct RevisionColumn{pub field:String,pub heading:String,pub width_mm:f64}
impl Default for RevisionColumn{fn default()->Self{Self{field:"Number".into(),heading:"Rev".into(),width_mm:15.0}}}
#[derive(Debug,Clone,PartialEq,Serialize,Deserialize)]
#[serde(default)]
pub struct RevisionTable{pub at:[f64;2],pub columns:Vec<RevisionColumn>,pub row_height_mm:f64,pub text_mm:f64,pub title:String,pub show_headers:bool,pub newest_first:bool,pub grow_up:bool,pub fixed_rows:Option<usize>,pub rotation:i32}
impl Default for RevisionTable{fn default()->Self{Self{at:[671.0,574.0],columns:vec![RevisionColumn::default(),RevisionColumn{field:"Date".into(),heading:"Date".into(),width_mm:25.0},RevisionColumn{field:"Description".into(),heading:"Description".into(),width_mm:110.0}],row_height_mm:8.0,text_mm:2.5,title:"REVISIONS".into(),show_headers:true,newest_first:false,grow_up:false,fixed_rows:None,rotation:0}}}
impl RevisionTable{pub fn check(&self)->Result<(),String>{let t=self;if ![0,90,270].contains(&t.rotation)||t.columns.is_empty()||t.columns.len()>12||t.columns.iter().any(|c|!REVISION_FIELDS.contains(&c.field.as_str())||!c.width_mm.is_finite()||c.width_mm<5.0)||!t.at.iter().all(|v|v.is_finite())||!t.row_height_mm.is_finite()||!t.text_mm.is_finite()||t.row_height_mm<3.0||t.text_mm<0.5||t.text_mm>t.row_height_mm||t.fixed_rows.is_some_and(|n|n==0||n>1000){Err("Check the revision table columns, size and rotation.".into())}else{Ok(())}}}

pub const REVISION_FIELDS:&[&str]=&["Number","Sequence","Date","Description","Issued To","Issued By","Issued"];

impl Document{
    pub fn revisions(&self)->Vec<(Id,&Revision)>{let mut out:Vec<_>=self.iter().filter_map(|(id,e)|match e{Element::Revision(r)=>Some((id,r)),_=>None}).collect();out.sort_by_key(|(id,r)|(r.order,*id));out}
    pub fn revision_record(&self,id:Id)->Option<&Revision>{match self.get(id){Some(Element::Revision(r))=>Some(r),_=>None}}
    pub fn revision_settings(&self)->RevisionSettings{self.iter().find_map(|(_,e)|match e{Element::RevisionSettings(s)=>Some(s.clone()),_=>None}).unwrap_or_default()}
    pub fn revision_clouds(&self,view:Id)->Vec<(Id,&RevisionCloud)>{self.iter().filter_map(|(id,e)|match e{Element::RevisionCloud(c)if c.view==view=>Some((id,c)),_=>None}).collect()}
    pub fn revision_tags(&self,view:Id)->Vec<(Id,&RevisionTag)>{self.iter().filter_map(|(id,e)|match e{Element::RevisionTag(t)if t.view==view=>Some((id,t)),_=>None}).collect()}
    pub fn add_revision(&mut self,sequence:&str)->Result<Id,String>{if !self.revision_settings().sequences.iter().any(|s|s.id==sequence){return Err("Unknown revision numbering sequence.".into());}let order=self.revisions().last().map_or(0,|(_,r)|r.order+1);let r=Revision{order,sequence:sequence.into(),date:String::new(),description:String::new(),issued_to:String::new(),issued_by:String::new(),issued:false,visibility:RevisionVisibility::default()};self.transact("Add revision",|tx|Ok(tx.add(Element::Revision(r))))}
    pub fn patch_revision(&mut self,id:Id,patch:&serde_json::Value)->Result<(),String>{let old=self.revision_record(id).ok_or("not a revision")?;let mut r:Revision=crate::doc::apply_patch(old,patch)?;r.order=old.order;if !self.revision_settings().sequences.iter().any(|s|s.id==r.sequence){return Err("Unknown revision numbering sequence.".into());}self.transact("Revision properties",|tx|tx.update(id,Element::Revision(r)))}
    pub fn set_revision_settings(&mut self,s:RevisionSettings)->Result<(),String>{
        if !s.arc_length_mm.is_finite()||s.arc_length_mm<0.5||s.arc_length_mm>100.0{return Err("Cloud arc length must be between 0.5 and 100 paper millimetres.".into());}let mut ids=std::collections::HashSet::new();for seq in &s.sequences{if seq.id.trim().is_empty()||seq.name.trim().is_empty()||!ids.insert(&seq.id)||seq.digits>10||seq.start>1000000||seq.kind==NumberingKind::Alphanumeric&&(seq.values.is_empty()||seq.values.iter().any(|v|v.trim().is_empty())){return Err("Check the sequence names, symbols and numeric settings.".into());}}
        if self.revisions().iter().any(|(_,r)|!s.sequences.iter().any(|seq|seq.id==r.sequence)){return Err("A numbering sequence is still used by a revision.".into());}let old=self.revision_settings();if self.revisions().iter().any(|(_,r)|r.issued)&&(s.numbering!=old.numbering||s.sequences!=old.sequences){return Err("Unissue the affected revisions before changing numbering.".into());}
        let id=self.iter().find_map(|(id,e)|matches!(e,Element::RevisionSettings(_)).then_some(id));self.transact("Revision settings",|tx|match id{Some(id)=>tx.update(id,Element::RevisionSettings(s)),None=>{tx.add(Element::RevisionSettings(s));Ok(())}})
    }
    pub fn reorder_revisions(&mut self,ids:&[Id])->Result<(),String>{let current=self.revisions();if ids.len()!=current.len()||ids.iter().collect::<std::collections::HashSet<_>>().len()!=ids.len()||ids.iter().any(|id|self.revision_record(*id).is_none()){return Err("Supply every revision once, in order.".into());}if current.iter().any(|(_,r)|r.issued)&&current.iter().map(|(id,_)|*id).collect::<Vec<_>>()!=ids{return Err("Unissue revisions before reordering the issue history.".into());}let updates:Vec<_>=ids.iter().enumerate().map(|(i,id)|{let mut r=self.revision_record(*id).unwrap().clone();r.order=i as u32;(*id,r)}).collect();self.transact("Reorder revisions",|tx|{for(id,r)in updates{tx.update(id,Element::Revision(r))?;}Ok(())})}
    pub fn revision_number(&self,id:Id,sheet:Option<Id>)->String{let Some(r)=self.revision_record(id)else{return String::new()};let settings=self.revision_settings();let Some(seq)=settings.sequences.iter().find(|s|s.id==r.sequence)else{return String::new()};let applicable=if settings.numbering==NumberingScope::Sheet{sheet.map(|s|self.sheet_revisions(s))}else{None};let index=self.revisions().into_iter().take_while(|(other,_)|*other!=id).filter(|(other,r)|r.sequence==seq.id&&applicable.as_ref().is_none_or(|a|a.contains(other))).count();let value=match seq.kind{NumberingKind::None=>return String::new(),NumberingKind::Numeric=>format!("{:0width$}",seq.start as usize+index,width=seq.digits),NumberingKind::Alphanumeric=>{let len=seq.values.len();if len==0{return String::new();}let mut i=index+seq.start.saturating_sub(1)as usize;let mut v=String::new();loop{v.insert_str(0,&seq.values[i%len]);if i<len{break;}i=i/len-1;}v}};format!("{}{}{}",seq.prefix,value,seq.suffix)}
    pub fn sheet_revisions(&self,sheet:Id)->Vec<Id>{let Some(s)=self.sheet(sheet)else{return vec![]};let views=self.sheet_views(sheet);self.revisions().into_iter().filter(|(id,_)|s.additional_revisions.contains(id)||self.iter().any(|(_,e)|match e{Element::RevisionCloud(c)if c.revision==*id=>c.view==sheet||views.iter().any(|v|v.view==c.view&&cloud_intersects(c,v)),_=>false})).map(|(id,_)|id).collect()}
    pub fn revision_value(&self,id:Id,sheet:Option<Id>,field:&str)->String{let Some(r)=self.revision_record(id)else{return String::new()};match field{"Number"=>self.revision_number(id,sheet),"Sequence"=>(r.order+1).to_string(),"Date"=>r.date.clone(),"Description"=>r.description.clone(),"Issued To"=>r.issued_to.clone(),"Issued By"=>r.issued_by.clone(),"Issued"=>if r.issued{"Yes"}else{"No"}.into(),_=>String::new()}}
    pub fn current_revision(&self,sheet:Id)->Option<Id>{self.sheet_revisions(sheet).last().copied()}
    pub fn set_sheet_revisions(&mut self,sheet:Id,ids:Vec<Id>)->Result<(),String>{if ids.iter().any(|id|self.revision_record(*id).is_none()){return Err("Unknown revision.".into());}let mut s=self.sheet(sheet).cloned().ok_or("not a sheet")?;s.additional_revisions=ids;self.set_sheet(sheet,s)}
    pub fn merge_revisions(&mut self,source:Id,target:Id)->Result<(),String>{if source==target||self.revision_record(source).is_none()||self.revision_record(target).is_none(){return Err("Choose two different revisions.".into());}if self.revision_record(source).unwrap().issued||self.revision_record(target).unwrap().issued{return Err("Unissue both revisions before merging.".into());}let changes:Vec<_>=self.iter().filter_map(|(id,e)|match e{Element::RevisionCloud(c)if c.revision==source=>{let mut c=c.clone();c.revision=target;Some((id,Element::RevisionCloud(c)))},Element::Sheet(s)if s.additional_revisions.contains(&source)=>{let mut s=s.clone();for id in &mut s.additional_revisions{if *id==source{*id=target;}}s.additional_revisions.sort();s.additional_revisions.dedup();Some((id,Element::Sheet(s)))},_=>None}).collect();self.transact("Merge revisions",|tx|{for(id,e)in changes{tx.update(id,e)?;}tx.remove(source)})}
    fn check_cloud(&self,c:&RevisionCloud,new_assignment:bool)->Result<(),String>{let r=self.revision_record(c.revision).ok_or("Choose a revision")?;if new_assignment&&r.issued{return Err("Cannot assign a cloud to an issued revision.".into());}self.check_detail_view(c.view)?;if c.curves.is_empty()||c.curves.iter().any(|c|c.tessellate(1.0).iter().any(|p|!p.x.is_finite()||!p.y.is_finite())){return Err("Draw a closed cloud boundary.".into());}crate::curve::sketch_loops(&c.curves).map_err(|e|format!("Cloud boundary: {e:?}"))?;Ok(())}
    pub fn add_revision_cloud(&mut self,c:RevisionCloud,tag:bool)->Result<Id,String>{self.check_cloud(&c,true)?;let view=c.view;let at=c.curves[0].start();self.grouped("Revision cloud",|d|{let id=d.transact("Cloud",|tx|Ok(tx.add(Element::RevisionCloud(c))))?;if tag{d.add_revision_tag(view,id,at)?;}Ok(id)})}
    pub fn patch_revision_cloud(&mut self,id:Id,patch:&serde_json::Value)->Result<(),String>{let Some(Element::RevisionCloud(old))=self.get(id)else{return Err("not a revision cloud".into())};let c:RevisionCloud=crate::doc::apply_patch(old,patch)?;if old.pinned&&(c.curves!=old.curves||c.view!=old.view){return Err("Unpin the cloud before changing its boundary.".into());}self.check_cloud(&c,c.revision!=old.revision)?;self.transact("Revision cloud properties",|tx|tx.update(id,Element::RevisionCloud(c)))}
    pub fn add_revision_tag(&mut self,view:Id,cloud:Id,at:Point)->Result<Id,String>{let Some(Element::RevisionCloud(c))=self.get(cloud)else{return Err("Choose a cloud".into())};if view!=c.view{return Err("Tag the cloud in its own view.".into());}let family=self.ensure_revision_tag_family();self.transact("Tag revision",|tx|Ok(tx.add(Element::RevisionTag(RevisionTag{view,cloud,at,family:Some(family),leader:true,pinned:false}))))}
    pub fn patch_revision_tag(&mut self,id:Id,patch:&serde_json::Value)->Result<(),String>{let Some(Element::RevisionTag(old))=self.get(id)else{return Err("not a revision tag".into())};let t:RevisionTag=crate::doc::apply_patch(old,patch)?;if old.pinned&&old.at!=t.at{return Err("Unpin the tag before moving it.".into());}if !t.at.x.is_finite()||!t.at.y.is_finite()||!matches!(self.get(t.cloud),Some(Element::RevisionCloud(c))if c.view==t.view)||t.family.is_some_and(|id|self.annotation_family(id).is_none_or(|f|f.kind!=crate::annotation::AnnotationKind::RevisionTag)){return Err("Invalid cloud, tag family or location.".into());}self.transact("Revision tag properties",|tx|tx.update(id,Element::RevisionTag(t)))}
    pub(crate) fn check_revision_change(&self,id:Id,before:&Element,after:Option<&Element>)->Result<(),String>{
        if let Element::Revision(r)=before{let renumbers=match after{None=>true,Some(Element::Revision(n))=>n.sequence!=r.sequence||n.order!=r.order,_=>true};if renumbers&&self.revisions().iter().any(|(other,issued)|*other!=id&&issued.issued&&issued.sequence==r.sequence&&issued.order>=r.order){return Err("Unissue later revisions before changing their numbering.".into());}}
        match before{
            Element::Revision(r)if r.issued=>{let Some(Element::Revision(n))=after else{return Err("Unissue the revision before deleting it.".into())};let mut allowed=r.clone();allowed.issued=n.issued;allowed.visibility=n.visibility;if &allowed!=n{return Err("Unissue the revision before editing it.".into());}},
            Element::RevisionCloud(c)if self.revision_record(c.revision).is_some_and(|r|r.issued)=>{if after!=Some(before){return Err("Unissue the revision before editing or deleting its clouds.".into());}},
            Element::Revision(_)=>{if after.is_none()&&(self.iter().any(|(_,e)|matches!(e,Element::RevisionCloud(c)if c.revision==id))||self.sheets().iter().any(|(_,s)|s.additional_revisions.contains(&id))){return Err("Remove or merge the revision's clouds and sheet assignments before deleting it.".into());}},
            _=>{}
        }Ok(())
    }
}

fn cloud_intersects(c:&RevisionCloud,v:&crate::sheet::PlacedView)->bool{let lo=[v.view_centre[0]-v.view_size[0]/2.0,v.view_centre[1]-v.view_size[1]/2.0];let hi=[lo[0]+v.view_size[0],lo[1]+v.view_size[1]];let inside=|p:Point|p.x>=lo[0]&&p.x<=hi[0]&&p.y>=lo[1]&&p.y<=hi[1];let mut pts=vec![];for curve in &c.curves{let line=curve.tessellate(1.0);if line.iter().any(|p|inside(*p)){return true;}for p in line.windows(2){if segment_box(p[0],p[1],lo,hi){return true;}}pts.extend(line);}crate::curve::point_in_polygon(Point::new(v.view_centre[0],v.view_centre[1]),&pts)}
fn segment_box(a:Point,b:Point,lo:[f64;2],hi:[f64;2])->bool{let mut t0:f64=0.0;let mut t1:f64=1.0;for(a,d,l,h)in[(a.x,b.x-a.x,lo[0],hi[0]),(a.y,b.y-a.y,lo[1],hi[1])]{if d.abs()<1e-10{if a<l||a>h{return false;}}else{let(x,y)=((l-a)/d,(h-a)/d);t0=t0.max(x.min(y));t1=t1.min(x.max(y));if t0>t1{return false;}}}true}
